import{_ as o,c as t,o as a,ae as d}from"./chunks/framework.DUl3UDQb.js";const i="/devDocs/assets/use-db-1.DYyLoDoD.png",h=JSON.parse('{"title":"常见使用说明","description":"","frontmatter":{},"headers":[],"relativePath":"AI赋能/hy插件/usage.md","filePath":"AI赋能/hy插件/usage.md"}'),c={name:"AI赋能/hy插件/usage.md"};function l(r,e,s,n,_,p){return a(),t("div",null,e[0]||(e[0]=[d('<h1 id="常见使用说明" tabindex="-1">常见使用说明 <a class="header-anchor" href="#常见使用说明" aria-label="Permalink to &quot;常见使用说明&quot;">​</a></h1><blockquote><p>hy 插件日常使用频率最高的场景速查：数据库查询、字典查询、设计图还原。 命令在三个平台（Claude Code / Codex / CodeBuddy）的用法差异见 <a href="./commands-matrix.html">三平台命令对照表</a>；MCP 服务完整触发说明见 <a href="./../MCP服务/">内部使用的 MCP 服务</a>。</p></blockquote><h2 id="_1-数据库【库】【表】查询" tabindex="-1">1. 数据库【库】【表】查询 <a class="header-anchor" href="#_1-数据库【库】【表】查询" aria-label="Permalink to &quot;1. 数据库【库】【表】查询&quot;">​</a></h2><p>开发前先让 AI 通过工具获取目标表的结构/字段信息，再按字段写页面、接口，避免凭记忆开发。</p><p><img src="'+i+'" alt="数据库查询"></p><p><strong>Prompt 示例</strong>：</p><blockquote><p>通过工具获取【审批表单配置表】的信息</p></blockquote><p><strong>使用要点</strong>：</p><ul><li>触发方式：<code>@hy:db</code> 专家直呼，或流程内自动触发（<code>run-crud</code> 表格字段梳理、<code>run-all</code> 数据设计前）</li><li>工具：<code>lookup_table_fields(表名/关键词)</code> 按表名或中文备注模糊搜索字段信息；<code>list_databases()</code> 列出可用数据库连接</li><li>首次使用需写入访问 token（找插件维护者要【测试环境接口】token）： <code>node ~/.hcoder/plugin/mcp/hy-db-tools/server.js --set-token &lt;token&gt;</code>（Windows 为 <code>~\\.hy\\plugin\\...</code>）</li><li>Token 失效时查询会立即停下向你要 token，写入后立即生效、无需重启</li><li>只读查询表结构/字段；DDL/DML 变更仍只出方案，由人工执行</li></ul><h2 id="_2-字典查询-enterprise-dict" tabindex="-1">2. 字典查询（enterprise-dict） <a class="header-anchor" href="#_2-字典查询-enterprise-dict" aria-label="Permalink to &quot;2. 字典查询（enterprise-dict）&quot;">​</a></h2><p>表单下拉 / 单元格回显 / 筛选条件 / 后端枚举字段需要可选值时，先查字典确认枚举是否已存在。</p><p><strong>使用要点</strong>：</p><ul><li><code>list_dicts_by_system</code>：用前端项目 <code>src/global/constant.js</code> 的 APP_NAME 查<strong>当前微服务所有字典</strong>（去 <code>-web</code> 作 systemFlag）</li><li><code>get_dict_options</code>：查询字典详情</li><li>新增字典：<code>create_dict</code>（新增字典集）/ <code>create_dict_item</code>（完善字典项）—— <strong>必须人工确认</strong>；提供系统编码、实体名、字段名和值（如 1-可用，2-禁用）</li><li>字典编码结构：<code>{系统编码}__{实体名}__{字段名}</code></li><li>使用 Trae 需切换智能体为 <strong>build with mcp</strong></li><li>禁止：猜测枚举值（描述不清先问用户）、新增<strong>其他系统</strong>的字典</li></ul><h2 id="_3-设计图还原-figma" tabindex="-1">3. 设计图还原（figma） <a class="header-anchor" href="#_3-设计图还原-figma" aria-label="Permalink to &quot;3. 设计图还原（figma）&quot;">​</a></h2><p>有 Figma 设计稿时，<code>@hy:ui</code> 专家读取设计稿提取视觉规范（design token），实现像素级高保真 UI。</p><p><strong>使用要点</strong>：</p><ul><li>触发方式：<code>run-screen</code> 步骤 6（设计图确认）、<code>run-all</code>（有设计稿时）、直接 <code>@hy:ui &lt;需求&gt;</code></li><li>工具：<code>mcp__figma__*</code>（本地 <code>http://127.0.0.1:3845/mcp</code>，需桌面端 Figma 客户端配合）</li><li>提取的视觉规范<strong>必须沉淀为文本</strong>（<code>.claude/design/04-ui/visual-spec.md</code> 或样式 token），AI 与后续编码只认文本</li><li>设计稿缺失/未授权/连接不可用时如实说明，改用 <code>04-ui/</code> 契约 + 项目设计系统兜底，不阻塞交付</li></ul><h2 id="_4-更多场景-待补充" tabindex="-1">4. 更多场景（待补充） <a class="header-anchor" href="#_4-更多场景-待补充" aria-label="Permalink to &quot;4. 更多场景（待补充）&quot;">​</a></h2><blockquote><p>其他常用场景将在此追加（含截图与触发说明）。如需补充，联系文档维护者或在仓库提交 PR。</p></blockquote>',19)]))}const g=o(c,[["render",l]]);export{h as __pageData,g as default};
